public object FfiConverterTypeGpucapEngine: FfiConverter<GpucapEngine, Pointer> {

    override fun lower(value: GpucapEngine): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): GpucapEngine {
        return GpucapEngine(value)
    }

    override fun read(buf: ByteBuffer): GpucapEngine {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: GpucapEngine) = 8UL

    override fun write(value: GpucapEngine, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



