sealed class GpucapCoreException: kotlin.Exception() {
    
    class AuthRequired(
        ) : GpucapCoreException() {
        override val message
            get() = ""
    }
    
    class Network(
        
        val `msg`: kotlin.String
        ) : GpucapCoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Http(
        
        val `code`: kotlin.UShort, 
        
        val `msg`: kotlin.String
        ) : GpucapCoreException() {
        override val message
            get() = "code=${ `code` }, msg=${ `msg` }"
    }
    
    class Decode(
        
        val `msg`: kotlin.String
        ) : GpucapCoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<GpucapCoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): GpucapCoreException = FfiConverterTypeGpucapCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeGpucapCoreError : FfiConverterRustBuffer<GpucapCoreException> {
    override fun read(buf: ByteBuffer): GpucapCoreException {
        

        return when(buf.getInt()) {
            1 -> GpucapCoreException.AuthRequired()
            2 -> GpucapCoreException.Network(
                FfiConverterString.read(buf),
                )
            3 -> GpucapCoreException.Http(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> GpucapCoreException.Decode(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: GpucapCoreException): ULong {
        return when(value) {
            is GpucapCoreException.AuthRequired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is GpucapCoreException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is GpucapCoreException.Http -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is GpucapCoreException.Decode -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: GpucapCoreException, buf: ByteBuffer) {
        when(value) {
            is GpucapCoreException.AuthRequired -> {
                buf.putInt(1)
                Unit
            }
            is GpucapCoreException.Network -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is GpucapCoreException.Http -> {
                buf.putInt(3)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is GpucapCoreException.Decode -> {
                buf.putInt(4)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



sealed class QrParseResult {
    
    data class Single(
        val `url`: kotlin.String) : QrParseResult() {
        companion object
    }
    
    data class Dual(
        val `ipv4`: kotlin.String, 
        val `ipv6`: kotlin.String) : QrParseResult() {
        companion object
    }
    
    object Invalid : QrParseResult()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeQrParseResult : FfiConverterRustBuffer<QrParseResult>{
    override fun read(buf: ByteBuffer): QrParseResult {
        return when(buf.getInt()) {
            1 -> QrParseResult.Single(
                FfiConverterString.read(buf),
                )
            2 -> QrParseResult.Dual(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> QrParseResult.Invalid
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: QrParseResult) = when(value) {
        is QrParseResult.Single -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`url`)
            )
        }
        is QrParseResult.Dual -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`ipv4`)
                + FfiConverterString.allocationSize(value.`ipv6`)
            )
        }
        is QrParseResult.Invalid -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: QrParseResult, buf: ByteBuffer) {
        when(value) {
            is QrParseResult.Single -> {
                buf.putInt(1)
                FfiConverterString.write(value.`url`, buf)
                Unit
            }
            is QrParseResult.Dual -> {
                buf.putInt(2)
                FfiConverterString.write(value.`ipv4`, buf)
                FfiConverterString.write(value.`ipv6`, buf)
                Unit
            }
            is QrParseResult.Invalid -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






